"""Pure Python Pomodoro state machine.

This module has no dependency on Qt, threads, or wall-clock time: it is
driven entirely by calls to :meth:`TimerEngine.tick`, which makes it
trivial to unit test and reuse from any front end (GUI, CLI, ...).
"""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from typing import Callable, Optional


class Phase(Enum):
    FOCUS = "focus"
    SHORT_BREAK = "short_break"
    LONG_BREAK = "long_break"


class RunState(Enum):
    IDLE = "idle"
    RUNNING = "running"
    PAUSED = "paused"
    FINISHED = "finished"


@dataclass(slots=True)
class TimerConfig:
    """User-configurable durations and round structure."""

    focus_minutes: float = 25.0
    break_minutes: float = 5.0
    long_break_minutes: float = 15.0
    rounds: int = 4
    long_break_enabled: bool = True
    long_break_interval: int = 4

    def phase_duration_seconds(self, phase: Phase) -> float:
        if phase is Phase.FOCUS:
            return max(self.focus_minutes, 0.0) * 60
        if phase is Phase.LONG_BREAK:
            return max(self.long_break_minutes, 0.0) * 60
        return max(self.break_minutes, 0.0) * 60


@dataclass(slots=True)
class PhaseEvent:
    """Emitted whenever a phase finishes naturally (its countdown hit zero)."""

    phase: Phase
    round_number: int


class TimerEngine:
    """A Focus -> Break -> Focus -> ... state machine that always ends on Focus.

    Drive it from any event loop by calling :meth:`tick` with the elapsed
    number of seconds since the previous tick (e.g. from a 1s ``QTimer``).
    """

    def __init__(
        self,
        config: TimerConfig,
        on_phase_complete: Optional[Callable[[PhaseEvent], None]] = None,
        on_session_complete: Optional[Callable[[], None]] = None,
        on_phase_aborted: Optional[Callable[[Phase, int, float], None]] = None,
    ) -> None:
        self.config = config
        self.on_phase_complete = on_phase_complete
        self.on_session_complete = on_session_complete
        self.on_phase_aborted = on_phase_aborted
        self.state: RunState = RunState.IDLE
        self.phase: Phase = Phase.FOCUS
        self.round_number: int = 1
        self.remaining_seconds: float = config.phase_duration_seconds(Phase.FOCUS)

    @property
    def total_seconds(self) -> float:
        return self.config.phase_duration_seconds(self.phase)

    @property
    def progress(self) -> float:
        """Fraction of the current phase elapsed, in ``[0, 1]``."""
        total = self.total_seconds
        if total <= 0:
            return 1.0
        return min(max(1.0 - (self.remaining_seconds / total), 0.0), 1.0)

    def start(self) -> None:
        if self.state in (RunState.IDLE, RunState.PAUSED):
            self.state = RunState.RUNNING

    def pause(self) -> None:
        if self.state is RunState.RUNNING:
            self.state = RunState.PAUSED

    def resume(self) -> None:
        self.start()

    def toggle_pause(self) -> None:
        if self.state is RunState.RUNNING:
            self.pause()
        elif self.state is RunState.PAUSED:
            self.resume()

    def stop(self) -> None:
        """Abort the current session and reset back to a fresh, idle Focus 1/N.

        If a Focus round was under way (running or paused), its elapsed time
        is reported via ``on_phase_aborted`` before the reset, so a cut-short
        round can still be counted as time actually worked instead of being
        silently discarded. Breaks are never reported this way — like a
        completed Break, an aborted one still isn't "work" — and nothing
        fires for an idle or already-finished session, since there is no
        partial progress to report in either case.
        """
        if self.state in (RunState.RUNNING, RunState.PAUSED) and self.phase is Phase.FOCUS:
            elapsed_seconds = self.total_seconds - self.remaining_seconds
            if elapsed_seconds > 0 and self.on_phase_aborted is not None:
                self.on_phase_aborted(self.phase, self.round_number, elapsed_seconds)

        self.state = RunState.IDLE
        self.phase = Phase.FOCUS
        self.round_number = 1
        self.remaining_seconds = self.config.phase_duration_seconds(Phase.FOCUS)

    def apply_config(self, config: TimerConfig) -> None:
        """Replace the config. Only takes effect immediately while idle."""
        self.config = config
        if self.state is RunState.IDLE:
            self.remaining_seconds = config.phase_duration_seconds(self.phase)

    def tick(self, delta_seconds: float) -> None:
        if self.state is not RunState.RUNNING or delta_seconds <= 0:
            return
        self.remaining_seconds -= delta_seconds
        # A while-loop (rather than a single if) guards against a very large
        # delta_seconds skipping over more than one phase boundary at once.
        while self.remaining_seconds <= 0 and self.state is RunState.RUNNING:
            overshoot = -self.remaining_seconds
            self._advance_phase()
            self.remaining_seconds -= overshoot

    def _next_phase_after_focus(self) -> Phase:
        if self.config.long_break_enabled and self.config.long_break_interval > 0:
            if self.round_number % self.config.long_break_interval == 0:
                return Phase.LONG_BREAK
        return Phase.SHORT_BREAK

    def _advance_phase(self) -> None:
        finished_phase = self.phase
        finished_round = self.round_number

        if self.on_phase_complete is not None:
            self.on_phase_complete(PhaseEvent(finished_phase, finished_round))

        if finished_phase is Phase.FOCUS:
            if finished_round >= self.config.rounds:
                self.state = RunState.FINISHED
                self.remaining_seconds = 0.0
                if self.on_session_complete is not None:
                    self.on_session_complete()
                return
            self.phase = self._next_phase_after_focus()
        else:
            self.round_number += 1
            self.phase = Phase.FOCUS

        self.remaining_seconds = self.config.phase_duration_seconds(self.phase)

"""SQLite-backed persistence for completed focus rounds and their stats."""

from __future__ import annotations

import sqlite3
from dataclasses import dataclass
from datetime import date, datetime, timedelta
from pathlib import Path

from .paths import app_data_dir

_DB_FILENAME = "pomodoro.db"

_SCHEMA = """
CREATE TABLE IF NOT EXISTS focus_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    completed_at TEXT NOT NULL,
    duration_minutes REAL NOT NULL,
    tag TEXT,
    completed INTEGER NOT NULL DEFAULT 1
);
"""


@dataclass(slots=True)
class SessionRecord:
    completed_at: datetime
    duration_minutes: float
    tag: str
    completed: bool = True


@dataclass(slots=True)
class StatsSummary:
    today_minutes: float = 0.0
    today_count: int = 0
    week_minutes: float = 0.0
    week_count: int = 0
    total_minutes: float = 0.0
    total_count: int = 0


class HistoryStore:
    """Append-only log of completed focus rounds, plus derived statistics."""

    def __init__(self, path: Path | None = None) -> None:
        self.path = path or (app_data_dir() / _DB_FILENAME)
        self._conn = sqlite3.connect(self.path)
        self._conn.execute(_SCHEMA)
        self._migrate()
        self._conn.commit()

    def _migrate(self) -> None:
        """Add columns introduced after a user's database already existed.

        ``CREATE TABLE IF NOT EXISTS`` only creates the table on a first run,
        so an existing ``pomodoro.db`` (from before the ``completed`` column
        was introduced in 0.2.0) needs it added explicitly. Rows written
        before this migration predate partial-round tracking entirely, so
        backfilling them as ``completed = 1`` reflects what was actually true
        at the time: only full rounds were ever recorded.
        """
        columns = {row[1] for row in self._conn.execute("PRAGMA table_info(focus_sessions)")}
        if "completed" not in columns:
            self._conn.execute("ALTER TABLE focus_sessions ADD COLUMN completed INTEGER NOT NULL DEFAULT 1")

    def close(self) -> None:
        self._conn.close()

    def record_focus_round(self, duration_minutes: float, tag: str = "", completed: bool = True) -> None:
        with self._conn:
            self._conn.execute(
                "INSERT INTO focus_sessions (completed_at, duration_minutes, tag, completed) VALUES (?, ?, ?, ?)",
                (datetime.now().isoformat(timespec="seconds"), duration_minutes, tag or "", int(completed)),
            )

    def _rows(self, tag: str | None = None) -> list[SessionRecord]:
        if tag:
            cursor = self._conn.execute(
                "SELECT completed_at, duration_minutes, tag, completed FROM focus_sessions "
                "WHERE tag = ? ORDER BY completed_at",
                (tag,),
            )
        else:
            cursor = self._conn.execute(
                "SELECT completed_at, duration_minutes, tag, completed FROM focus_sessions ORDER BY completed_at"
            )
        return [
            SessionRecord(datetime.fromisoformat(completed_at), duration_minutes, tag or "", bool(completed))
            for completed_at, duration_minutes, tag, completed in cursor.fetchall()
        ]

    def distinct_tags(self) -> list[str]:
        cursor = self._conn.execute(
            "SELECT DISTINCT tag FROM focus_sessions WHERE tag IS NOT NULL AND tag != '' ORDER BY tag"
        )
        return [row[0] for row in cursor.fetchall()]

    def summary(self, tag: str | None = None) -> StatsSummary:
        rows = self._rows(tag)
        today = date.today()
        week_start = today - timedelta(days=today.weekday())  # Monday

        summary = StatsSummary()
        for row in rows:
            summary.total_minutes += row.duration_minutes
            summary.total_count += 1
            row_date = row.completed_at.date()
            if row_date == today:
                summary.today_minutes += row.duration_minutes
                summary.today_count += 1
            if row_date >= week_start:
                summary.week_minutes += row.duration_minutes
                summary.week_count += 1
        return summary

    def daily_totals(self, days: int = 7, tag: str | None = None) -> list[tuple[date, float]]:
        """Total focus minutes per day for the last ``days`` days (oldest first)."""
        rows = self._rows(tag)
        today = date.today()
        buckets: dict[date, float] = {today - timedelta(days=offset): 0.0 for offset in range(days - 1, -1, -1)}
        cutoff = today - timedelta(days=days - 1)
        for row in rows:
            row_date = row.completed_at.date()
            if row_date >= cutoff:
                buckets[row_date] = buckets.get(row_date, 0.0) + row.duration_minutes
        return sorted(buckets.items())

    def reset(self) -> None:
        with self._conn:
            self._conn.execute("DELETE FROM focus_sessions")
